22: // HijackRequests creates a new router instance for requests hijacking.
23: // When use Fetch domain outside the router should be stopped. Enabling hijacking disables page caching,
24: // but such as 304 Not Modified will still work as expected.
25: // The entire process of hijacking one request:
26: //
27: //	browser --req-> rod ---> server ---> rod --res-> browser
28: //
29: // The --req-> and --res-> are the parts that can be modified.
30: func (p *Page) HijackRequests() *HijackRouter {
31: 	return newHijackRouter(p.browser, p).initEvents()
32: }
