34: // HijackRouter context.
35: type HijackRouter struct {
36: 	run      func()
37: 	stop     func()
38: 	handlers []*hijackHandler
39: 	enable   *proto.FetchEnable
40: 	client   proto.Client
41: 	browser  *Browser
42: }
43: 
44: func newHijackRouter(browser *Browser, client proto.Client) *HijackRouter {
45: 	return &HijackRouter{
46: 		enable:   &proto.FetchEnable{},
47: 		browser:  browser,
48: 		client:   client,
49: 		handlers: []*hijackHandler{},
50: 	}
51: }
