53: func (r *HijackRouter) initEvents() *HijackRouter { //nolint: gocognit
54: 	ctx := r.browser.ctx
55: 	if cta, ok := r.client.(proto.Contextable); ok {
56: 		ctx = cta.GetContext()
57: 	}
58: 
59: 	var sessionID proto.TargetSessionID
60: 	if tsa, ok := r.client.(proto.Sessionable); ok {
61: 		sessionID = tsa.GetSessionID()
62: 	}
63: 
64: 	eventCtx, cancel := context.WithCancel(ctx)
65: 	r.stop = cancel
66: 
67: 	_ = r.enable.Call(r.client)
68: 
69: 	r.run = r.browser.Context(eventCtx).eachEvent(sessionID, func(e *proto.FetchRequestPaused) bool {
70: 		go func() {
71: 			ctx := r.new(eventCtx, e)
72: 			for _, h := range r.handlers {
73: 				if !h.regexp.MatchString(e.Request.URL) {
74: 					continue
75: 				}
76: 
77: 				h.handler(ctx)
